import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Models","description":"","frontmatter":{"title":"Models"},"headers":[],"relativePath":"docs/settings/models.md","filePath":"docs/settings/models.md","lastUpdated":1790449305000}'),l={name:"docs/settings/models.md"};function d(r,e,n,i,c,u){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h1><p>Settings → Models is where you choose what powers chat and analysis in OrbySystems. See <a href="/docs/concepts/llm-models">LLM models</a> for the concept; this page covers the settings themselves.</p><h2 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models&quot;">​</a></h2><p>OrbySystems can run a model directly on your machine, in a few different sizes. A suitable size is suggested based on your hardware, and it&#39;s downloaded the first time it&#39;s needed — see <a href="/docs/getting-started/install-orby">Install OrbySystems</a> for what to expect the first time.</p><h2 id="cloud-models" tabindex="-1">Cloud models <a class="header-anchor" href="#cloud-models" aria-label="Permalink to &quot;Cloud models&quot;">​</a></h2><p>You can instead (or additionally) connect a cloud model via a standard API endpoint. This is entirely optional — OrbySystems works fully offline with a local model.</p><h2 id="trusted-vs-untrusted" tabindex="-1">Trusted vs. untrusted <a class="header-anchor" href="#trusted-vs-untrusted" aria-label="Permalink to &quot;Trusted vs. untrusted&quot;">​</a></h2><p>Your main, trusted model is the one with access to your actual project data. You can separately configure untrusted supporting models for other backend tasks — these are never given access to your data.</p><h2 id="before-you-rely-on-a-model" tabindex="-1">Before you rely on a model <a class="header-anchor" href="#before-you-rely-on-a-model" aria-label="Permalink to &quot;Before you rely on a model&quot;">​</a></h2><p>Use <a href="/docs/tools/model-test">Model Test</a> to confirm a newly configured model works correctly with OrbySystems, and <a href="/docs/tools/model-eval-suite">Model Eval Suite</a> to compare how well and how fast different models answer real finance questions.</p>',10)])])}const f=o(l,[["render",d]]);export{h as __pageData,f as default};
